@Test
    void testShuffleMatchesPermutationSamplerShuffleDirectional_1_oe() {
        final List<Integer> orig = new ArrayList<>();
        for (int i = 0; i < 10; i++) {
            orig.add((i + 1) * rng.nextInt());
        }

        assertShuffleMatchesPermutationSamplerShuffle(new ArrayList<>(orig), 4, true);
    }

